-- sqlite DDL for `wikipedia_simple`, generated by megasamples from the MySQL corpus. Do not edit:
-- the next port rewrites it. Data is loaded from the MySQL Shell dump, not from here.

CREATE TABLE "category" (
  "cat_id" INTEGER PRIMARY KEY,
  "cat_title" BLOB NOT NULL DEFAULT X'',
  "cat_pages" INTEGER NOT NULL DEFAULT 0,
  "cat_subcats" INTEGER NOT NULL DEFAULT 0,
  "cat_files" INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE "categorylinks" (
  "cl_from" INTEGER NOT NULL DEFAULT 0,
  "cl_sortkey" BLOB NOT NULL DEFAULT X'',
  "cl_timestamp" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "cl_sortkey_prefix" BLOB NOT NULL DEFAULT X'',
  "cl_type" TEXT NOT NULL DEFAULT 'page' CHECK ("cl_type" IN ('page', 'subcat', 'file')),
  "cl_collation_id" SMALLINT NOT NULL DEFAULT 0,
  "cl_target_id" BIGINT NOT NULL,
  PRIMARY KEY ("cl_from", "cl_target_id")
);

CREATE TABLE "linktarget" (
  "lt_id" INTEGER PRIMARY KEY,
  "lt_namespace" INTEGER NOT NULL,
  "lt_title" BLOB NOT NULL
);

CREATE TABLE "page" (
  "page_id" INTEGER PRIMARY KEY,
  "page_namespace" INTEGER NOT NULL DEFAULT 0,
  "page_title" BLOB NOT NULL DEFAULT X'',
  "page_is_redirect" TINYINT NOT NULL DEFAULT 0,
  "page_is_new" TINYINT NOT NULL DEFAULT 0,
  "page_random" DOUBLE NOT NULL DEFAULT 0,
  "page_touched" BLOB NOT NULL,
  "page_links_updated" BLOB,
  "page_latest" INTEGER NOT NULL DEFAULT 0,
  "page_len" INTEGER NOT NULL DEFAULT 0,
  "page_content_model" BLOB,
  "page_lang" BLOB
);

CREATE TABLE "pagelinks" (
  "pl_from" INTEGER NOT NULL DEFAULT 0,
  "pl_from_namespace" INTEGER NOT NULL DEFAULT 0,
  "pl_target_id" BIGINT NOT NULL,
  PRIMARY KEY ("pl_from", "pl_target_id")
);

CREATE TABLE "redirect" (
  "rd_from" INTEGER NOT NULL DEFAULT 0,
  "rd_namespace" INTEGER NOT NULL DEFAULT 0,
  "rd_title" BLOB NOT NULL DEFAULT X'',
  "rd_interwiki" BLOB,
  "rd_fragment" BLOB,
  PRIMARY KEY ("rd_from")
);

CREATE TABLE "revision" (
  "rev_id" INTEGER NOT NULL,
  "rev_page" INTEGER NOT NULL,
  "rev_parent_id" INTEGER,
  "rev_timestamp" DATETIME NOT NULL,
  "rev_minor_edit" TINYINT NOT NULL DEFAULT 0,
  "rev_len" INTEGER,
  "rev_sha1" BLOB,
  "rev_user_id" INTEGER,
  "rev_user_text" BLOB,
  "rev_comment" TEXT,
  "rev_content_model" BLOB,
  PRIMARY KEY ("rev_id")
);

CREATE TABLE "site_stats" (
  "ss_row_id" INTEGER NOT NULL DEFAULT 0,
  "ss_total_edits" BIGINT,
  "ss_good_articles" BIGINT,
  "ss_total_pages" BIGINT,
  "ss_users" BIGINT,
  "ss_images" BIGINT,
  "ss_active_users" BIGINT,
  "ss_temp_users" BIGINT,
  "ss_active_temp_users" BIGINT,
  PRIMARY KEY ("ss_row_id")
);

CREATE TABLE "text" (
  "old_id" INTEGER NOT NULL,
  "old_text" TEXT,
  PRIMARY KEY ("old_id")
);

CREATE INDEX "category_cat_pages" ON "category" ("cat_pages");
CREATE UNIQUE INDEX "category_cat_title" ON "category" ("cat_title");
CREATE INDEX "categorylinks_cl_sortkey_id" ON "categorylinks" ("cl_target_id", "cl_type", "cl_sortkey", "cl_from");
CREATE INDEX "categorylinks_cl_timestamp_id" ON "categorylinks" ("cl_target_id", "cl_timestamp");
CREATE UNIQUE INDEX "linktarget_lt_namespace_title" ON "linktarget" ("lt_namespace", "lt_title");
CREATE INDEX "page_page_len" ON "page" ("page_len");
CREATE UNIQUE INDEX "page_page_name_title" ON "page" ("page_namespace", "page_title");
CREATE INDEX "page_page_random" ON "page" ("page_random");
CREATE INDEX "page_page_redirect_namespace_len" ON "page" ("page_is_redirect", "page_namespace", "page_len");
CREATE INDEX "pagelinks_pl_backlinks_namespace_target_id" ON "pagelinks" ("pl_from_namespace", "pl_target_id", "pl_from");
CREATE INDEX "pagelinks_pl_target_id" ON "pagelinks" ("pl_target_id", "pl_from");
CREATE INDEX "redirect_rd_ns_title" ON "redirect" ("rd_namespace", "rd_title", "rd_from");
